{"code": """"Authorization decision engine using deny-overrides algorithm."""


def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide an access request against a set of policies.

    Applies the deny-overrides combining algorithm: any matching DENY policy
    results in "DENY", otherwise at least one matching ALLOW policy results in
    "ALLOW", otherwise returns "DENY" (default deny).

    Args:
        request: Dict with keys "subject", "roles" (list), "action", "resource".
        policies: List of policy dicts with keys "effect", "principal", "action", "resource".

    Returns:
        "ALLOW" or "DENY".

    Raises:
        ValueError: If request or any policy is malformed.
    """
    # Validate request and all policies before making any decisions
    _validate_request(request)
    for policy in policies:
        _validate_policy(policy)

    # Find matching policies
    matching_policies = [p for p in policies if _policy_matches(request, p)]

    # Apply deny-overrides combining algorithm
    # 1. Any DENY policy wins
    for policy in matching_policies:
        if policy["effect"] == "DENY":
            return "DENY"

    # 2. At least one ALLOW policy results in ALLOW
    if any(p["effect"] == "ALLOW" for p in matching_policies):
        return "ALLOW"

    # 3. Default deny: no matching policies
    return "DENY"


def _validate_request(request: dict) -> None:
    """Validate request has required fields."""
    required = {"subject", "roles", "action", "resource"}
    for field in required:
        if field not in request:
            raise ValueError(f"Request missing required field: {field}")

    if not isinstance(request["roles"], list):
        raise ValueError("Request 'roles' must be a list")


def _validate_policy(policy: dict) -> None:
    """Validate policy has required fields and valid effect."""
    required = {"effect", "principal", "action", "resource"}
    for field in required:
        if field not in policy:
            raise ValueError(f"Policy missing required field: {field}")

    effect = policy["effect"]
    if effect not in ("ALLOW", "DENY"):
        raise ValueError(f"Invalid effect: {effect}")


def _policy_matches(request: dict, policy: dict) -> bool:
    """Check if a policy matches the request on all three dimensions."""
    return (
        _principal_matches(request, policy["principal"])
        and _pattern_matches(request["action"], policy["action"])
        and _pattern_matches(request["resource"], policy["resource"])
    )


def _principal_matches(request: dict, principal: str) -> bool:
    """Check if principal matches request subject or roles."""
    if principal == "*":
        return True

    if principal.startswith("user:"):
        user = principal[5:]
        return user == request["subject"]

    if principal.startswith("role:"):
        role = principal[5:]
        return role in request["roles"]

    return False


def _pattern_matches(value: str, pattern: str) -> bool:
    """Check if value matches pattern (with trailing * glob support)."""
    if pattern.endswith("*"):
        prefix = pattern[:-1]
        return value.startswith(prefix)
    else:
        return value == pattern
